let selectedSubject=null,myTeachingSubjects=[],catalogPublishedFor='';
import {renderMaterial,MATERIAL_TYPES} from './material-media.js';
import * as D from './spark-db.js';
import {safeLink,splitExam,gradeAttempt,SAMPLE,publicAnswers,risk,validateBackup} from './spark-model.js';
import {parseClassroomRoster} from './roster.js';
let user,profile,isAdmin=false,course,courseId,unsubs=[],assessment=null,examId='',demoMode=false;
const $=id=>document.getElementById(id),app=$('app'),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),id=()=>crypto.randomUUID(),now=()=>D.serverTimestamp(),cp=()=>`sparkCourses/${courseId}`,ep=()=>`${cp()}/exams/${examId}`;
const owner=()=>isAdmin||course?.ownerUid===user?.uid;
const subjectManager=(subject=selectedSubject)=>owner()||(profile?.role==='teacher'&&myTeachingSubjects.includes(subject));
const visibleSubjects=()=>profile?.role==='teacher'&&!owner()?subjectsOf(course).filter(subject=>myTeachingSubjects.includes(subject)):subjectsOf(course);
function stop(){for(const f of unsubs)f();unsubs=[];assessment=null;}
function error(e){console.error(e);$('toast').textContent=e.code==='permission-denied'?'Acesso negado. Confira aprovação, matrícula e permissões no curso.':e.message||String(e);$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',9000);}
function on(key,fn){if($(key))$(key).onclick=async()=>{const b=$(key);b.disabled=true;try{await fn();}catch(e){error(e);}finally{if(b.isConnected)b.disabled=false;}};}
function page(title,html,back=parentScreen(title)){stop();app.innerHTML=`<div class="screen-navigation"><button id="screen-back" class="outline" ${back?'':'disabled'}>← Voltar</button></div><h1>${esc(title)}</h1>${html}`;let changed=false;app.oninput=()=>{changed=true;};on('screen-back',async()=>{if((changed||assessment)&&!confirm('Voltar sem salvar as alterações ou respostas desta tela?'))return;if(back)await back();});}
function parentScreen(title){const cid=courseId,subject=selectedSubject;if(['Minha plataforma','Aprender, avaliar e acompanhar.'].includes(title))return null;if(title==='Adicionar conteúdo'||title==='Editar conteúdo'||title==='Organizar assuntos e ordem')return lessons;if(title==='Cadastro de avaliação'||title.startsWith('Quiz ao vivo')||title.startsWith('Entregas ·')||title==='Sua entrega')return exams;if(title.startsWith('Correção ·'))return async()=>reviewList(await D.read(ep()));if(title.startsWith('Histórico ·'))return tracking;if(title.startsWith('Conteúdos ·')||title.startsWith('Avaliações e quizzes ·')||title.startsWith('Acompanhamento ·')||title==='Relatório de conselho')return ()=>subject?subjectHome(subject):openCourse(cid);if(course&&title===course.title)return home;if(subjectsOf(course).includes(title))return ()=>openCourse(cid);if(['Adicionar disciplinas','Configurar curso','Acompanhamento geral','Equipe de acompanhamento','Coordenação e professores','Revisar vínculos de disciplinas','Curso encerrado','Fechamento do curso / ano'].includes(title))return ()=>openCourse(cid);return home;}

function field(k,label,value='',type='text'){return `<label for="${k}">${label}</label><input id="${k}" type="${type}" value="${esc(value)}">`;}
const area=(k,label,value='')=>`<label for="${k}">${label}</label><textarea id="${k}" rows="7">${esc(value)}</textarea>`;
const select=(k,label,items,value)=>`<label for="${k}">${label}</label><select id="${k}">${items.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select>`;
const val=k=>$(k).value.trim(),button=(k,text,cls='')=>`<button id="${k}" class="${cls}">${text}</button>`;
function download(name,data,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([type==='application/json'?JSON.stringify(data,null,2):data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),10000);}
function link(url,label='Abrir documento'){if(!url)return '';try{return `<a href="${esc(safeLink(url))}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;}catch{return '<span>Link inválido</span>';}}
function table(head,rows){return `<div style="overflow:auto"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function date(v){return v?.toDate? v.toDate().toLocaleString('pt-BR'):String(v||'');}
function nav(){ $('account').innerHTML=user?`<span>${esc(user.displayName)}</span> ${button('home','Início','outline')} ${button('out','Sair','outline')}`:button('login','Entrar com Google');on('login',D.login);on('home',home);on('out',D.logout);}
function landing(){page('Aprender, avaliar e acompanhar.',`<p>Conexões reúne cursos, avaliações e acompanhamento da turma.</p><div class="card"><h2>Acesso à plataforma</h2><p>Entre com sua conta Google. Professores e estudantes precisam de aprovação.</p>${button('enter','Entrar com Google')}</div><p>Conheça o sistema: entre com Google e escolha a demonstração. Usamos nome, telefone e e-mail para registrar seu interesse.</p>`);on('enter',D.login);}
D.onAuthStateChanged(D.auth,async u=>{user=u;try{nav();if(!u){profile=null;isAdmin=false;return landing();}isAdmin=!!await D.read('sparkAdmins/'+u.uid);profile=await D.read('sparkProfiles/'+u.uid);await home();if(profile?.status==='active'||isAdmin)await routeLink();}catch(e){error(e);}});
async function home(){nav();if(!profile&&!isAdmin)return register();if(isAdmin&&!profile)profile={name:user.displayName,role:'admin',status:'active'};if(profile.status!=='active'&&!isAdmin){page('Cadastro aguardando aprovação',`<p>Seu UID: <code>${esc(user.uid)}</code></p><p>A administração precisa aprovar seu acesso.</p>${button('refresh','Verificar aprovação')} ${button('demo','Conhecer demonstração')}`);on('refresh',async()=>{profile=await D.read('sparkProfiles/'+user.uid);home();});on('demo',demoSignup);return;}
if(profile.role==='teacher'&&profile.status==='active'){const signature=[user.uid,profile.institution,profile.campus].join('|');if(catalogPublishedFor!==signature){await publishInstitution(profile).then(()=>{catalogPublishedFor=signature;}).catch(e=>console.warn('Catálogo institucional pendente de sincronização administrativa',e.code));}}
let courses=isAdmin?await D.list('sparkCourses'):await D.list('sparkCourses',[['viewerUids','array-contains',user.uid]]);if(profile.role==='teacher'&&!isAdmin){const own=await D.list('sparkCourses',[['ownerUid','==',user.uid]]);courses=[...new Map([...courses,...own].map(c=>[c.id,c])).values()];}
page('Minha plataforma',`<p>${esc(profile.name)} · ${esc(profile.institution)} / ${esc(profile.campus)}</p><p class="muted">Seu UID: <code>${esc(user.uid)}</code></p><div class="actions">${isAdmin?button('admin','Administração'):''}${profile.role==='teacher'?button('new-course','Novo curso'):''}${button('join','Matrícula por código','outline')}${button('demo','Demonstração','outline')}${profile.role==='teacher'?button('bank','Banco de questões','outline')+button('renew','Meu plano / renovação','outline')+button('campuses','Instituição e campi','outline'):''}${isAdmin?button('backup','Backup e restauração','outline'):''}</div><div class="grid">${courses.map(c=>`<article class="card"><span class="pill">${c.closed?'Encerrado':'Em andamento'}</span><h2>${esc(c.title)}</h2><p>${esc(c.group)} · ${esc(c.periods?.join(', '))}</p>${button('c-'+c.id,'Abrir curso')}</article>`).join('')||'<p>Você ainda não tem cursos. Use o código de matrícula fornecido pelo professor.</p>'}</div>`);
for(const c of courses)on('c-'+c.id,()=>openCourse(c.id));on('new-course',()=>courseEditor());on('admin',adminPanel);on('join',joinCourse);on('demo',demoSignup);on('backup',backupPanel);on('bank',bankPanel);on('renew',renewPlan);on('campuses',campusPanel);}
async function register(){
 const institutions=await D.list('sparkInstitutions');
 page('Seu cadastro',`${field('name','Nome completo',user.displayName)}${field('phone','Telefone')}${select('role','Perfil',[['student','Estudante'],['teacher','Professor'],['staff','Equipe de acompanhamento']],'student')}<div id="registration-institution-fields"></div>${button('register','Enviar cadastro')} ${button('demo','Conhecer demonstração','outline')}`,user?home:landing);
 const refreshCampuses=()=>{const teacher=val('role')==='teacher',key=val('institution-select'),entry=institutions.find(i=>i.id===key);$('new-institution-fields').hidden=key!=='__new__';const campuses=entry?.campuses||[];$('registration-campus-fields').innerHTML=select('campus-select','Campus',[['','Selecione o campus'],...campuses.map(name=>[name,name]),...(teacher?[['__new__','Cadastrar campus não listado']]:[])],teacher&&!campuses.length?'__new__':'')+`<div id="new-campus-fields">${field('new-campus','Nome do novo campus')}</div>`;$('campus-select').onchange=()=>{$('new-campus-fields').hidden=val('campus-select')!=='__new__';};$('campus-select').onchange();};
 const refreshInstitutions=()=>{const teacher=val('role')==='teacher';$('registration-institution-fields').innerHTML=select('institution-select','Instituição',[['','Selecione a instituição'],...institutions.map(i=>[i.id,i.name]),...(teacher?[['__new__','Cadastrar instituição não listada']]:[])],teacher&&!institutions.length?'__new__':'')+`<div id="new-institution-fields">${field('new-institution','Nome da instituição')}</div><div id="registration-campus-fields"></div><p class="muted">${teacher?'Novos nomes informados no cadastro entram na lista compartilhada após a aprovação do professor.':'Selecione uma instituição e campus cadastrados. Se não encontrar o campus, solicite o cadastro a um professor.'}</p>`;$('institution-select').onchange=refreshCampuses;refreshCampuses();};
 $('role').onchange=refreshInstitutions;refreshInstitutions();
 on('register',async()=>{const role=val('role'),selected=val('institution-select'),entry=institutions.find(i=>i.id===selected);if(!val('name'))throw Error('Informe seu nome.');if(!entry&&!(role==='teacher'&&selected==='__new__'))throw Error('Selecione uma instituição cadastrada.');const institution=entry?.name||campusName(val('new-institution')),campusChoice=val('campus-select');if(!campusChoice||campusChoice==='__new__'&&role!=='teacher')throw Error('Selecione um campus cadastrado.');const campus=campusChoice==='__new__'?campusName(val('new-campus')):campusChoice;if(campusChoice!=='__new__'&&!entry?.campuses?.includes(campus))throw Error('O campus não pertence à instituição selecionada.');await D.put('sparkProfiles/'+user.uid,{uid:user.uid,name:val('name'),phone:val('phone'),email:user.email,institution,institutionKey:entry?.id||institutionKey(institution),campus,role,status:'pending',createdAt:now()});profile=await D.read('sparkProfiles/'+user.uid);await home();});on('demo',demoSignup);
}

async function demoSignup(){const lead=await D.read('sparkLeads/'+user.uid);if(lead)return showDemo();page('Conheça a plataforma',`<p>Cadastre seu interesse para abrir uma demonstração com dados fictícios, sem acesso a turmas reais.</p>${field('lead-name','Nome',user.displayName)}${field('lead-phone','Telefone')}${field('lead-email','E-mail da conta Google',user.email,'email')}<label><input type="checkbox" id="consent"> Concordo com o registro destes dados para contato sobre o sistema.</label>${button('lead-send','Abrir demonstração')}`);$('lead-email').readOnly=true;on('lead-send',async()=>{if(!val('lead-name')||!val('lead-phone')||!$('consent').checked)throw Error('Informe nome, telefone e confirme o registro.');await D.put('sparkLeads/'+user.uid,{name:val('lead-name'),phone:val('lead-phone'),email:user.email,createdAt:now()});showDemo();});}
function showDemo(){page('Demonstração · dados fictícios',`<p>Ambiente ilustrativo. As ações abaixo não alteram o banco de dados.</p><div class="actions">${button('d-course','Curso')}${button('d-exam','Avaliação')}${button('d-track','Acompanhamento')}${button('d-back','Voltar','outline')}</div><div id="demo-content" class="card"></div>`);on('d-back',home);on('d-course',()=>{$('demo-content').innerHTML='<h2>Redes de computadores</h2><p>Turma INF1 · 1º, 2º e 3º trimestres</p><progress max="100" value="65"></progress><p>65% dos conteúdos concluídos</p><ul><li>Half-duplex e full-duplex</li><li>Aprendizagem da tabela MAC</li><li>ARP na rede local</li></ul>';});on('d-exam',()=>{$('demo-content').innerHTML='<h2>Questão de demonstração</h2><p>Half-duplex permite enviar e receber ao mesmo tempo?</p>'+button('d-yes','Sim')+button('d-no','Não')+'<p id="d-result"></p>';on('d-yes',()=>{$('d-result').textContent='Revise: no half-duplex há alternância.';});on('d-no',()=>{$('d-result').textContent='Correto. No full-duplex há envio e recepção simultâneos.';});});on('d-track',()=>{$('demo-content').innerHTML=table(['Estudante','1º trimestre','2º trimestre','Situação'],[['Ana fictícia','A','B','Regular'],['Bruno fictício','D','D','<strong style="color:#b42318">Acompanhamento prioritário</strong>']]);});$('d-course').click();}
async function adminPanel(){const people=await D.list('sparkProfiles');for(const person of people)if(person.role==='teacher'&&person.status==='active')await publishInstitution(person);const plans=await D.list('sparkPlans'),payments=await D.list('sparkPlanPayments');page('Administração',`<h2>Aprovação de cadastros</h2><p>Selecione vários estudantes e aprove em lote. Perfis de professor e equipe são aprovados individualmente.</p>${table(['Selecionar','Nome / UID','Perfil','Instituição / campus','Status','Ação'],people.map(p=>[`<input type="checkbox" data-approve="${p.id}" ${p.role!=='student'?'disabled':''}>`,`${esc(p.name)}<br><code>${esc(p.id)}</code>`,esc(p.role),esc(p.institution)+' / '+esc(p.campus),esc(p.status),button('u-'+p.id,p.status==='active'?'Suspender':'Aprovar')]))}${button('bulk','Aprovar estudantes selecionados')}<h2>Planos e renovação</h2><p>Os comprovantes são links externos. A administração confere o pagamento e registra a validade. O limite de questões é validado nas regras. Os limites de alunos e de respostas são orientativos nesta edição.</p>${field('target','UID do professor')}${field('plan','Plano','free')}${field('until','Validade do plano pago','', 'date')}${field('proof','Link HTTPS do comprovante')}${button('assign-plan','Registrar plano e pagamento')}<h3>Solicitações de renovação</h3>${table(['Professor (UID)','Plano','Ciclo','Comprovante'],payments.map(p=>[esc(p.uid),esc(p.planId),esc(p.cycle),link(p.receiptLink)]))}<h3>Configuração de planos</h3>${area('plans','Planos em JSON',JSON.stringify(plans.length?plans.map(({id,...p})=>({id,...p})):[{id:'free',title:'Free',active:true,price:0,maxStudents:30,maxQuestions:10,maxResponses:30,features:{tracking:true,team:true,warnings:true,questionBank:true}}],null,2))}${button('save-plans','Salvar planos')}<h2>Interessados na demonstração</h2>${button('leads','Consultar cadastros')}<div id="leads-out"></div>`);for(const p of people)on('u-'+p.id,async()=>{await D.patch('sparkProfiles/'+p.id,{status:p.status==='active'?'suspended':'active'});if(p.role==='teacher'&&p.status!=='active')await publishInstitution(p);adminPanel();});on('bulk',async()=>{await D.batch([...document.querySelectorAll('[data-approve]:checked')].map(x=>{const p=people.find(p=>p.id===x.dataset.approve);return {path:'sparkProfiles/'+p.id,data:{...p,status:'active'}};}));adminPanel();});on('assign-plan',async()=>{safeLink(val('proof'));const patch={planId:val('plan'),planReceiptLink:val('proof'),planExpiresAt:val('until')?D.Timestamp.fromDate(new Date(val('until')+'T23:59:59-03:00')):D.Timestamp.fromMillis(0)};await D.patch('sparkProfiles/'+val('target'),patch);alert('Registro atualizado.');});on('save-plans',async()=>{const a=JSON.parse(val('plans'));if(!Array.isArray(a)||a.some(p=>!p.id||! /^[\w-]+$/.test(p.id)))throw Error('Planos inválidos.');await D.batch(a.map(({id,...p})=>({path:'sparkPlans/'+id,data:p})));alert('Planos salvos.');});on('leads',async()=>{$('leads-out').innerHTML=table(['Nome','Telefone','E-mail'],(await D.list('sparkLeads')).map(x=>[esc(x.name),esc(x.phone),esc(x.email)]));});}
function courseEditor(existing){const c=existing||{},known=subjectsOf(c),mode=c.subjectMode||(known.length>1?'multiple':'single');page(existing?'Configurar curso':'Novo curso',`${field('title','Nome do curso',c.title)}${field('group','Turma',c.group)}${select('subject-mode','Organização do curso',[['single','Uma disciplina'],['multiple','Várias disciplinas']],mode)}<p>As disciplinas serão cadastradas dentro do curso, depois de salvar.</p>${field('periods','Períodos, separados por vírgula',c.periods?.join(', ')||'1º trimestre, 2º trimestre, 3º trimestre')}${field('start','Início',c.start,'date')}${field('end','Fim',c.end,'date')}${select('free','Acesso',[['yes','Gratuito'],['no','Pago com aprovação manual'] ],c.free===false?'no':'yes')}${field('price','Valor total do curso',c.price||0,'number')}${field('share','Percentual do responsável (registro)',c.revenuePercent||0,'number')}${field('header','Cabeçalho das advertências',c.warningHeader)}${field('footer','Rodapé das advertências',c.warningFooter)}${field('letterhead','Link HTTPS do papel timbrado (PDF/editável)',c.letterhead)}${button('save-course','Salvar curso')}`);on('save-course',async()=>{const subjects=known;if(val('subject-mode')==='single'&&subjects.length>1)throw Error('O curso já tem várias disciplinas. Preserve a organização ou remova disciplinas sem histórico na área Adicionar disciplinas.');if(!val('title')||!val('group')||!val('start')||!val('end')||val('end')<val('start'))throw Error('Preencha título, turma e datas válidas.');safeLink(val('letterhead'));const cid=existing?.id||id();const data={coordinatorName:c.coordinatorName||profile.name,title:val('title'),group:val('group'),subjectMode:val('subject-mode'),subjects,periods:val('periods').split(',').map(s=>s.trim()).filter(Boolean),start:val('start'),end:val('end'),free:val('free')==='yes',price:Number(val('price')),revenuePercent:Number(val('share')),warningHeader:val('header'),warningFooter:val('footer'),letterhead:val('letterhead'),ownerUid:c.ownerUid||user.uid,institution:c.institution||profile.institution,campus:c.campus||profile.campus,viewerUids:c.viewerUids||[user.uid],closed:false};await D.put('sparkCourses/'+cid,data);await D.put('sparkInvites/'+cid,{title:data.title,group:data.group,institution:data.institution,campus:data.campus});openCourse(cid);});}
async function openCourse(cid){courseId=cid;selectedSubject=null;course=await D.read(cp());if(!course)throw Error('Curso não encontrado.');if(owner())await initializeLessonRelease(await D.list(cp()+'/lessons'));myTeachingSubjects=owner()?subjectsOf(course):(await D.read(cp()+'/instructors/'+user.uid).catch(()=>null))?.subjects||[];const team=owner()?null:await D.read(`${cp()}/team/${user.uid}`).catch(()=>null);const staff=owner()||!!team,subjects=visibleSubjects();if(subjects.length===1)selectedSubject=subjects[0];page(course.title,`<p>${esc(course.institution)} / ${esc(course.campus)} · ${esc(course.group)} · ${esc(course.start)} a ${esc(course.end)}</p><p><strong>Coordenador:</strong> ${esc(course.coordinatorName||course.ownerUid)}</p><p><strong>Código de matrícula:</strong> <code>${esc(cid)}</code></p><p>${link(shareUrl(cid),'Link deste curso')}</p>${course.closed?'<div class="notice">Curso encerrado. Novos lançamentos estão bloqueados.</div>':''}<div class="actions">${subjects.length===1?button('lessons','Conteúdos')+button('exams','Avaliações e quizzes'):''}${staff?button('track','Acompanhamento e conselho'):''}${owner()?button('roster','Matrículas e pagamentos'):''}${owner()?button('add-subjects','Adicionar disciplinas')+button('settings','Configurar curso','outline')+button('subject-links','Revisar vínculos de disciplinas','outline'):''}${owner()?button('teachers','Professores das disciplinas')+button('team','Equipe','outline'):''}${staff?button('report','Relatório acumulativo','outline'):''}${owner()?button('closure','Fechamento anual','outline'):''}</div><h2>${subjects.length===1?'Disciplina do curso':'Disciplinas do curso'}</h2><div class="grid">${subjects.map((subject,i)=>`<article class="card"><span class="pill">Disciplina</span><h3>${esc(subject)}</h3><p>Conteúdos, avaliações e resultados desta disciplina.</p>${button('subject-'+i,'Abrir disciplina')}</article>`).join('')||'<p>Use Adicionar disciplinas para começar a organizar os conteúdos e avaliações.</p>'}</div>`);subjects.forEach((subject,i)=>on('subject-'+i,()=>subjectHome(subject)));on('settings',()=>courseEditor(course));on('add-subjects',subjectsPanel);on('subject-links',reviewSubjectLinks);on('lessons',lessons);on('exams',exams);on('roster',roster);on('team',teamPanel);on('teachers',instructorsPanel);on('track',()=>{selectedSubject=null;return tracking();});on('report',()=>{selectedSubject=null;return report();});on('closure',closure);}
function joinCourse(){page('Solicitar matrícula',`${field('join-code','Código do curso')}${field('join-proof','Comprovante de pagamento: link HTTPS (se necessário)')}${button('send-request','Enviar solicitação')}`);on('send-request',async()=>{const cid=val('join-code');if(!/^[\w-]+$/.test(cid))throw Error('Código inválido.');const invite=await D.read('sparkInvites/'+cid);if(!invite)throw Error('Curso não encontrado.');safeLink(val('join-proof'));await D.put(`sparkCourses/${cid}/requests/${user.uid}`,{uid:user.uid,name:profile.name,status:'pending',receiptLink:val('join-proof'),createdAt:now()});alert('Matrícula solicitada em '+invite.title+'. O professor aprovará seu acesso.');home();});}
async function roster(){const requests=await D.list(cp()+'/requests'),students=await D.list(cp()+((owner()||!myTeachingSubjects.length)?'/students':'/roster'));const candidates=await D.list('sparkProfiles',[['role','==','student'],['campus','==',course.campus],['institution','==',course.institution]]);page('Matrículas e pagamentos',`<p>Para cursos pagos, confira o comprovante antes de aprovar. Informe a validade de acesso para a seleção.</p>${field('valid-until','Acesso válido até (curso pago)',course.end,'date')}${table(['Selecionar','Nome','Comprovante','Status'],candidates.map(p=>{const m=students.find(s=>s.id===p.id),r=requests.find(s=>s.id===p.id);return [`<input type="checkbox" data-enroll="${p.id}">`,`${esc(p.name)}<br><small>${esc(p.email)}</small>`,r?link(r.receiptLink):'',m?.active?'Ativa':'Pendente'];}))}${button('approve-enroll','Aprovar matrículas selecionadas')}<h2>Importar Google Classroom</h2><p>O JSON será lido para localizar estudantes pelo e-mail. A importação não cria contas Google. Alunos precisam entrar e cadastrar-se primeiro; cadastros de estudantes pendentes do mesmo campus são aprovados ao confirmar as matrículas.</p><input id="roster-file" type="file" accept="application/json">${button('roster-preview','Localizar estudantes do JSON')}<div id="roster-preview-out"></div>`);on('approve-enroll',async()=>{const ids=[...document.querySelectorAll('[data-enroll]:checked')].map(x=>x.dataset.enroll);if(!ids.length)throw Error('Selecione estudantes.');if(!course.free&&!val('valid-until'))throw Error('Informe validade do acesso pago.');for(const uid of ids){const p=candidates.find(p=>p.id===uid);if(p.status==='pending')await D.patch('sparkProfiles/'+uid,{status:'active'});else if(p.status!=='active')throw Error(p.name+' está suspenso. Solicite liberação administrativa.');await D.put(cp()+'/students/'+uid,{uid,name:p.name,email:p.email,active:true,validUntil:D.Timestamp.fromDate(new Date((val('valid-until')||course.end)+'T23:59:59-03:00')),receiptLink:requests.find(r=>r.id===uid)?.receiptLink||'',approvedBy:user.uid,approvedAt:now()});await D.put(cp()+'/roster/'+uid,{uid,name:p.name,email:p.email,active:true});await D.patch(cp(),{viewerUids:D.arrayUnion(uid)});if(requests.some(r=>r.id===uid))await D.remove(cp()+'/requests/'+uid);}roster();});on('roster-preview',async()=>{const f=$('roster-file').files[0];if(!f||f.size>5000000)throw Error('Escolha um JSON de até 5 MB.');const parsed=parseClassroomRoster(JSON.parse(await f.text()));const a=Array.isArray(parsed)?parsed:parsed.rows||parsed.students||[];let found=0;for(const p of candidates){const yes=a.some(r=>String(r.email||r.emailAddress||'').toLowerCase()===p.email.toLowerCase());if(yes){document.querySelector(`[data-enroll="${p.id}"]`).checked=true;found++;}}$('roster-preview-out').textContent=`${found} cadastros correspondentes selecionados. Confira e clique em Aprovar matrículas.`;});}
async function teamPanel(){const members=await D.list(cp()+'/team');page('Equipe de acompanhamento',`<p>A equipe pode ler o acompanhamento de todo este curso. As permissões abaixo controlam seus lançamentos. Use cursos separados para restringir disciplinas.</p>${field('team-uid','UID da pessoa aprovada pela administração')}${field('team-name','Nome / função')}<label><input id="observe" type="checkbox" checked> Observações</label><label><input id="council" type="checkbox"> Conselho de classe</label><label><input id="warnings" type="checkbox"> Advertências</label>${button('add-team','Salvar membro')}${table(['Nome / função','UID','Permissões','Ação'],members.map(m=>[esc(m.name),esc(m.uid),esc(m.permissions.join(', ')),button('rm-'+m.id,'Revogar','danger')]))}`);on('add-team',async()=>{const uid=val('team-uid');await D.put(cp()+'/team/'+uid,{uid,name:val('team-name'),permissions:['observe','council','warnings'].filter(k=>$(k).checked)});await D.patch(cp(),{viewerUids:D.arrayUnion(uid)});teamPanel();});for(const m of members)on('rm-'+m.id,async()=>{await D.remove(cp()+'/team/'+m.id);const teaching=await D.read(cp()+'/instructors/'+m.id);if(!teaching)await removeInstructorViewer(m.id);teamPanel();});}
function subjectHome(subject){assertSubject(course,subject);if(profile.role==='teacher'&&!subjectManager(subject))throw Error('Esta disciplina não está atribuída a você.');selectedSubject=subject;page(subject,`<p>${esc(course.title)} · ${esc(course.group)}</p><div class="actions">${button('subject-lessons','Conteúdos')}${button('subject-exams','Avaliações e quizzes')}${subjectManager()?button('subject-track','Conceitos e acompanhamento'):''}${subjectManager()?button('subject-report','Conselho desta disciplina','outline'):''}${button('subject-back','Voltar ao curso','outline')}</div>`,()=>openCourse(courseId));on('subject-lessons',lessons);on('subject-exams',exams);on('subject-track',tracking);on('subject-report',report);on('subject-back',()=>openCourse(courseId));}
