async function lessons(topicFilter=''){
 if(!requireSubject())return;
 const filters=[['subject','==',selectedSubject]];if(!subjectManager())filters.push(['releaseAt','<=',await D.serverNow()]);let loaded=await D.list(cp()+'/lessons',filters);if(subjectManager())loaded=await initializeLessonRelease(loaded);const items=orderedLessons(loaded),progress=await D.read(cp()+'/progress/'+user.uid).catch(()=>null),completed=progress?.completed||[];
 page('Conteúdos · '+selectedSubject,`${subjectManager()&&!course.closed?button('add-lesson','Adicionar conteúdo')+button('organize-lessons','Organizar assuntos e ordem','outline'):''}${topicNames(items).length?select('lesson-topic-filter','Filtrar por assunto',[['','Todos os assuntos'],...topicNames(items).map(topic=>[topic,topic])],topicFilter):''}${button('refresh-lessons','Atualizar conteúdos','outline')}<p class="muted">${items.filter(l=>completed.includes(l.id)).length} de ${items.length} conteúdos desta disciplina marcados como concluídos.</p><div class="actions lesson-expand-controls">${button('expand-all-lessons','Expandir todos','outline')}${button('collapse-all-lessons','Ocultar todos','outline')}</div><div class="lesson-list">${items.filter(l=>!topicFilter||l.topic===topicFilter).map((l,i)=>`<article class="card lesson-card"><header class="lesson-heading"><div><span class="lesson-subject">${esc(l.subject)}</span>${l.topic?`<span class="lesson-topic">${esc(l.topic)}</span>`:''}<h2>${esc(l.title)}</h2>${subjectManager()?`<p class="lesson-release-status">${esc(releaseLabel(l))}</p>`:''}</div><span class="lesson-number">${String(i+1).padStart(2,'0')}</span></header><details class="lesson-details"><summary><span class="lesson-expand-label">Expandir texto e materiais</span><span class="lesson-collapse-label">Ocultar texto e materiais</span></summary><div class="lesson-expanded"><div class="lesson-body">${String(l.body||'').split(/\n\s*\n/).filter(Boolean).map(t=>`<p>${esc(t).replace(/\n/g,'<br>')}</p>`).join('')}</div>${l.url?`<div class="lesson-primary">${renderMaterial({title:l.primaryTitle||'Material de estudo',url:l.url,type:l.urlType||'auto',description:l.urlDescription||''},{primary:true})}</div>`:''}${Array.isArray(l.materials)&&l.materials.length?`<div class="lesson-resources-heading"><h3>Explore os materiais</h3><p>Assista, observe e aprofunde o conteúdo.</p></div><div class="materials-grid">${l.materials.map(m=>renderMaterial(m)).join('')}</div>`:''}</div></details><div class="lesson-actions">${subjectManager()&&!course.closed?`${button('edit-lesson-'+l.id,'Editar conteúdo','outline')}${button('add-material-'+l.id,'Adicionar material','outline')}`:''}${!subjectManager()?button('done-'+l.id,completed.includes(l.id)?'Concluído':'Marcar como concluído'):''}</div></article>`).join('')}</div>`);
 on('refresh-lessons',()=>lessons(topicFilter));on('expand-all-lessons',()=>{for(const item of document.querySelectorAll('.lesson-details'))item.open=true;});on('collapse-all-lessons',()=>{for(const item of document.querySelectorAll('.lesson-details'))item.open=false;});on('add-lesson',()=>lessonEditor());on('organize-lessons',organizeLessons);if($('lesson-topic-filter'))$('lesson-topic-filter').onchange=()=>lessons(val('lesson-topic-filter'));
 for(const l of items){
  on('edit-lesson-'+l.id,()=>lessonEditor(l));
  on('add-material-'+l.id,()=>lessonEditor(l,true));
  on('done-'+l.id,async()=>{await D.put(cp()+'/progress/'+user.uid,{completed:[...new Set([...completed,l.id])],updatedAt:now()});lessons();});
 }
}
function lessonEditor(existing=null,addMaterial=false){
 const l=existing||{},subjects=owner()?subjectsOf(course):visibleSubjects();
 page(existing?'Editar conteúdo':'Adicionar conteúdo',`${field('lesson-title','Título',l.title)}${field('lesson-topic','Assunto / unidade (opcional)',l.topic)}${field('lesson-order','Ordem de apresentação (opcional)',l.order??'','number')}${select('lesson-subject','Disciplina',[['','Selecione uma disciplina'],...subjects.map(subject=>[subject,subject])],l.subject||selectedSubject||'')}${!subjects.length?'<p class="notice">Cadastre as disciplinas nas configurações do curso antes de adicionar conteúdo.</p>':''}${l.subject&&!subjects.includes(l.subject)?'<p class="notice">A disciplina anterior não está mais cadastrada. Selecione uma disciplina atual para salvar.</p>':''}${select('lesson-release-mode','Liberação do conteúdo',[['instant','Liberar imediatamente'],['scheduled','Agendar data e horário']],l.releaseMode||'instant')}<div id="lesson-schedule-fields">${field('lesson-release-at','Data e horário de liberação — Brasília (UTC−03:00)',scheduledInput(l.releaseAt),'datetime-local')}</div><p class="muted">Conteúdos agendados ficam invisíveis para os alunos até o horário indicado.</p>${area('lesson-body','Texto',l.body)}${field('lesson-url','Link HTTPS do material principal (opcional)',l.url)}${field('lesson-primary-title','Título do material principal',l.primaryTitle||'Material de estudo')}${select('lesson-url-type','Tipo do material principal',MATERIAL_TYPES,l.urlType||'auto')}${field('lesson-url-description','Resumo / orientação de leitura (opcional)',l.urlDescription)}<h2>Materiais adicionais</h2><p>Adicione links de vídeos, imagens e PDFs. Use a detecção automática ou selecione o tipo. Para imagens, prefira o endereço direto do arquivo. As permissões continuam sendo controladas no serviço de origem.</p><div id="lesson-materials"></div>${button('lesson-add-material','Adicionar outro material','outline')}<div class="actions">${button('lesson-save',existing?'Salvar alterações':'Salvar conteúdo')}${button('lesson-cancel','Cancelar','outline')}</div>`);
 const updateSchedule=()=>{$('lesson-schedule-fields').hidden=val('lesson-release-mode')!=='scheduled';};$('lesson-release-mode').onchange=updateSchedule;updateSchedule();const appendMaterial=(m={})=>{const key=id(),row=document.createElement('section');row.className='card';row.dataset.materialRow=key;row.innerHTML=`${field('material-title-'+key,'Nome do material',m.title)}${field('material-url-'+key,'Link HTTPS',m.url)}${select('material-type-'+key,'Tipo do material',MATERIAL_TYPES,m.type||'auto')}${field('material-description-'+key,'Resumo, orientação ou descrição da imagem (opcional)',m.description)}${button('material-remove-'+key,'Remover este material','outline')}`;$('lesson-materials').appendChild(row);on('material-remove-'+key,()=>row.remove());return row;};
 for(const m of Array.isArray(l.materials)?l.materials:[])appendMaterial(m);
 if(addMaterial){const row=appendMaterial();row.querySelector('input').focus();}
 on('lesson-add-material',()=>appendMaterial().querySelector('input').focus());
 on('lesson-cancel',lessons);
 on('lesson-save',async()=>{
  if(!val('lesson-title'))throw Error('Informe o título do conteúdo.');
  if(!val('lesson-subject')||!subjects.includes(val('lesson-subject')))throw Error('Selecione uma disciplina cadastrada no curso.');
  const release=releaseSetting(val('lesson-release-mode'),val('lesson-release-at'));safeLink(val('lesson-url'));
  const materials=[...document.querySelectorAll('[data-material-row]')].map(row=>{const inputs=row.querySelectorAll('input');return {title:inputs[0].value.trim(),url:inputs[1].value.trim(),type:row.querySelector('select').value,description:inputs[2].value.trim()};}).filter(m=>m.title||m.url);
  for(const m of materials){if(!m.title||!m.url)throw Error('Preencha o nome e o link de cada material adicional.');safeLink(m.url);}
  const {id:previousId,...previous}=l;
  await D.put(cp()+'/lessons/'+(previousId||id()),{...previous,releaseMode:release.mode,releaseAt:D.Timestamp.fromMillis(release.millis),title:val('lesson-title'),subject:val('lesson-subject'),body:val('lesson-body'),topic:val('lesson-topic'),order:val('lesson-order')===''?null:Number(val('lesson-order')),url:val('lesson-url'),urlType:val('lesson-url-type'),primaryTitle:val('lesson-primary-title'),urlDescription:val('lesson-url-description'),materials,updatedAt:now()});
  await lessons();
 });
}

async function exams(){if(!requireSubject())return;const filters=[['subject','==',selectedSubject],...(subjectManager()?[]:[['published','==',true]])];const list=await D.list(cp()+'/exams',filters);page('Avaliações e quizzes · '+selectedSubject,`${subjectManager()&&!course.closed?button('new-exam','Cadastrar avaliação'):''}${list.map(e=>`<article class="card"><h2>${esc(e.title)}</h2><p>${esc(e.subject)} · ${esc(e.date)} · ${esc(availabilityStatus(e))} · ${e.grading==='concept'?'Conceito':'Nota'}</p><p><strong>${e.mode==='live'?'Quiz ao vivo':'Avaliação individual'}</strong></p><p>${e.mode==='live'?link(shareUrl(courseId,e.id,true),'Entrar no quiz ao vivo'):link(shareUrl(courseId,e.id),'Link da avaliação')}</p><div class="actions">${e.mode==='live'?button('live-'+e.id,subjectManager()?'Conduzir quiz ao vivo':'Entrar no quiz ao vivo'):button('e-'+e.id,subjectManager()?'Respostas e correção':'Responder')}${subjectManager()?button('edit-'+e.id,'Editar','outline'):''}${subjectManager()?button('availability-'+e.id,'Liberação e encerramento','outline')+button('toggle-'+e.id,e.open?'Encerrar respostas':'Liberar agora','outline')+button('responses-'+e.id,'Consultar respostas','outline'):''}</div></article>`).join('')}`);on('new-exam',()=>examEditor());for(const e of list){on('e-'+e.id,()=>{examId=e.id;return subjectManager()?reviewList(e):takeExam(e);});on('responses-'+e.id,()=>{examId=e.id;return responseReport(e);});on('edit-'+e.id,()=>examEditor(e));on('availability-'+e.id,()=>{examId=e.id;return examAvailability(e);});on('toggle-'+e.id,async()=>{examId=e.id;if(e.open)await closeExam(e);else await releaseExamNow(e);await exams();});on('live-'+e.id,()=>{examId=e.id;return live(e);});}}
async function examEditor(existing){
 const key=existing?await D.read(`${cp()}/exams/${existing.id}/private/key`):null;
 const data=existing?{...existing,questions:existing.questions.map(q=>key.keys[q.id])}:{title:'',subject:selectedSubject,date:'',grading:'concept',scale:100,questions:[]};
 page('Cadastro de avaliação',`${field('exam-title','Título da avaliação',data.title)}${select('exam-mode','Formato',[['assessment','Avaliação individual'],['live','Quiz ao vivo']],data.mode||'assessment')}${select('exam-subject','Disciplina',(owner()?subjectsOf(course):visibleSubjects()).map(subject=>[subject,subject]),data.subject)}${field('exam-date','Data de referência (opcional)',data.date,'date')}${availabilityFields(data)}${select('exam-grading','Forma de avaliação',[['concept','Conceito A, B, C ou D'],['grade','Nota numérica']],data.grading)}${field('exam-scale','Nota máxima da avaliação',data.scale,'number')}<p class="muted">As questões têm pesos individuais. O resultado é convertido para nota ou conceito ao corrigir.</p><h2>Questões</h2><div id="question-list"></div>${button('add-question','Adicionar questão','outline')}${button('exam-bank','Adicionar questão do banco','outline')}<div id="exam-bank-list"></div><div class="actions">${button('exam-save','Salvar avaliação')}${button('exam-cancel','Cancelar','outline')}</div>`,exams);
 wireAvailability();const editor=mountQuestionEditor($('question-list'),data.questions,{onError:error});if(!data.questions.length)editor.append();
 on('add-question',()=>editor.append());on('exam-bank',async()=>{const bank=await D.list('sparkBank',[['ownerUid','==',user.uid]]);$('exam-bank-list').innerHTML=bank.length?bank.map((entry,i)=>`<div class="card"><p>${esc(entry.question.prompt)}</p>${button('use-bank-'+i,'Usar questão','outline')}</div>`).join(''):'<p>Seu banco de questões está vazio.</p>';bank.forEach((entry,i)=>on('use-bank-'+i,()=>{editor.append({...structuredClone(entry.question),id:id()});}));});on('exam-cancel',exams);
 on('exam-save',async()=>{const examData={mode:val('exam-mode'),title:val('exam-title'),subject:assertSubject(course,val('exam-subject')),date:val('exam-date'),grading:val('exam-grading'),scale:Number(val('exam-scale')),questions:editor.read()};
 if(!examData.title)throw Error('Informe o título da avaliação.');if(!examData.questions.length)throw Error('Adicione pelo menos uma questão.');
 for(let i=0;i<examData.questions.length;i++){try{splitExam({...examData,questions:[examData.questions[i]]});}catch{throw Error('Revise a questão '+(i+1)+': enunciado, peso, alternativas/gabarito ou respostas das lacunas.');}}
 const split=splitExam(examData),eid=existing?.id||id(),windowData=readAvailability();
 if(examData.mode==='live'&&examData.questions.some(q=>q.type==='blanks'))throw Error('Quiz ao vivo aceita alternativas e respostas abertas. Use lacunas na avaliação individual.');const publicData={mode:examData.mode,title:examData.title,subject:examData.subject,date:examData.date,grading:examData.grading,scale:examData.scale,questions:split.questions,published:true,...windowData};
 if(existing&&((await D.list(`${cp()}/exams/${eid}/attempts`)).length||(await D.list(`${cp()}/exams/${eid}/liveAnswers`)).length))throw Error('Esta avaliação já tem entregas. Crie outra para alterar questões e pesos.');
 await D.batch([{path:`${cp()}/exams/${eid}`,data:publicData},{path:`${cp()}/exams/${eid}/private/key`,data:{keys:split.keys}}]);await exams();});
}

function question(q){let prompt=esc(q.prompt);if(q.type==='blanks')prompt=prompt.replace(/\{\{(\d+)\}\}/g,(_,n)=>`<input aria-label="Lacuna ${n}" style="display:inline-block;width:180px" maxlength="100">`);return `<section class="card" id="q-${q.id}"><h2>${prompt}</h2>${q.code?`<pre style="background:#101418;color:#e8edf2;padding:20px;overflow:auto"><code>${esc(q.code)}</code></pre>`:''}${['choice','multiple'].includes(q.type)?q.options.map((s,i)=>`<label class="option"><input type="${q.type==='choice'?'radio':'checkbox'}" name="${q.id}" value="${i}">${esc(s)}</label>`).join(''):q.type==='open'?`<textarea rows="5" maxlength="20000" aria-label="Resposta" style="${q.responseFormat==='code'?'background:#101418;color:#e8edf2;font-family:monospace':''}"></textarea>`:''}</section>`;}
async function takeExam(e){if(e.mode==='live')return live(e);examId=e.id;const prev=await D.read(ep()+'/attempts/'+user.uid);if(prev){const grade=await D.read(ep()+'/grades/'+user.uid);page('Sua entrega',`<p>Enviada em ${date(prev.submittedAt)}.</p>${grade?`<h2>${e.grading==='concept'?esc(grade.concept):grade.grade+' / '+e.scale}</h2>${Object.entries(grade.feedback).map(([k,v])=>`<p><strong>${esc(k)}</strong>: ${v.points} pontos · ${esc(v.feedback)}</p>`).join('')}`:'<p>Aguardando correção do professor.</p>'}`);return;}const state=await assertExamWindow(e,false);if(!state){page('Avaliação indisponível',`<p>${esc(availabilityStatus(e))}. Atualize a lista para conferir a liberação.</p>`,exams);return;}page(e.title,`<p>${esc(e.subject)} · Respostas enviadas uma única vez.</p><div class="notice">Saídas de foco e ações de copiar/colar podem ser registradas para análise do professor. Não comprovam fraude. O navegador não bloqueia nem detecta capturas de tela de forma confiável.</div>${e.questions.map(question).join('')}${button('submit','Enviar respostas')}`,exams);assessment=e;on('submit',async()=>{const answers={};for(const q of e.questions)answers[q.id]=publicAnswers(q,$('q-'+q.id));if(!confirm('Enviar definitivamente? Depois não será possível alterar.'))return;await assertExamWindow(e,true);await D.put(ep()+'/attempts/'+user.uid,{uid:user.uid,name:profile.name,answers,submittedAt:now()});assessment=null;takeExam(e);});}
let lastEvent=0;async function logEvent(type){if(!assessment||!user||Date.now()-lastEvent<1500)return;lastEvent=Date.now();try{await D.put(ep()+'/events/'+id(),{uid:user.uid,type,createdAt:now()});}catch(e){console.warn('Evento não registrado',e.code);}}
document.addEventListener('visibilitychange',()=>{if(document.hidden)logEvent('hidden');});window.addEventListener('blur',()=>logEvent('blur'));for(const t of ['copy','paste','contextmenu'])document.addEventListener(t,()=>logEvent(t));
async function reviewList(e){const attempts=await D.list(ep()+'/attempts'),grades=await D.list(ep()+'/grades');page('Entregas · '+e.title,table(['Aluno','Entregue em','Resultado','Ação'],attempts.map(a=>{const g=grades.find(g=>g.id===a.uid);return [esc(a.name),date(a.submittedAt),g?e.grading==='concept'?g.concept:g.grade:'A corrigir',button('review-'+a.uid,'Corrigir')];})));for(const a of attempts)on('review-'+a.uid,()=>review(e,a));}
async function review(e,a){const key=await D.read(ep()+'/private/key'),events=await D.list(ep()+'/events',[['uid','==',a.uid]]),previous=await D.read(ep()+'/grades/'+a.uid);page('Correção · '+a.name,`${e.questions.map(q=>`<section class="card"><h2>${esc(q.prompt)}</h2><pre style="white-space:pre-wrap">${esc(JSON.stringify(a.answers[q.id],null,2))}</pre>${q.type==='open'?field('points-'+q.id,`Pontos (0 a ${q.points})`,previous?.feedback?.[q.id]?.points||0,'number'):'<p>Correção automática ao salvar no painel do professor.</p>'}${field('feedback-'+q.id,'Feedback',previous?.feedback?.[q.id]?.feedback||'')}</section>`).join('')}${select('grade-period','Período para lançar no conselho',course.periods.map(p=>[p,p]),course.periods[0])}${field('deduction','Desconto em pontos brutos (após análise do professor)',0,'number')}${field('reason','Justificativa do desconto')}${button('grade-save','Calcular e publicar resultado')}<h2>Registros de navegação</h2><p>Eventos são indícios técnicos, não prova de fraude. Não há detecção garantida de prints.</p>${table(['Evento','Momento'],events.map(v=>[esc(v.type),date(v.createdAt)]))}`);on('grade-save',async()=>{const manual={};for(const q of e.questions)manual[q.id]={points:Number($('points-'+q.id)?.value||0),feedback:val('feedback-'+q.id)};const g=gradeAttempt(e,key.keys,a.answers,manual),discount=Number(val('deduction'));if(!Number.isFinite(discount)||discount<0||discount>g.total||(discount>0&&!val('reason')))throw Error('Desconto inválido ou sem justificativa.');g.earned=Math.max(0,g.earned-discount);g.percent=g.earned/g.total*100;g.grade=Math.round(g.percent/100*e.scale*100)/100;g.concept=g.percent>=99.999?'A':g.percent>=70?'B':g.percent>=40?'C':'D';await D.put(ep()+'/grades/'+a.uid,{...g,subject:e.subject,grading:e.grading,scale:e.scale,discount,reason:val('reason'),authorUid:user.uid,authorName:profile.name,updatedAt:now()});await D.put(cp()+'/records/'+id(),{kind:'result',studentUid:a.uid,studentName:a.name,subject:e.subject,period:val('grade-period'),grading:e.grading,concept:g.concept,grade:g.grade,scale:e.scale,text:'Avaliação: '+e.title,authorUid:user.uid,authorName:profile.name,createdAt:now()}).catch(err=>{console.warn('Lançamento no acompanhamento indisponível',err.code);});reviewList(e);});}
async function live(e){if(e.mode==='assessment')throw Error('Esta atividade é uma avaliação individual.');examId=e.id;const state=await D.read(ep()+'/live/state');if(!subjectManager()){page('Quiz ao vivo · '+e.title,'<div id="live-student">Aguardando professor…</div>');const render=s=>{if(!s||!s.open){$('live-student').innerHTML='<p>Aguarde a abertura da pergunta.</p>';return;}const q=e.questions.find(q=>q.id===s.questionId);if(!q)return;const sent=localStorage.getItem(`spark-live-${courseId}-${examId}-${user.uid}-${q.id}`);$('live-student').innerHTML=sent?'<p>Resposta enviada. Aguarde a próxima pergunta.</p>':question(q)+button('live-send','Enviar');on('live-send',async()=>{const answer=publicAnswers(q,$('q-'+q.id));await assertExamWindow(e,true);await D.put(ep()+'/liveAnswers/'+user.uid+'_'+q.id,{uid:user.uid,name:profile.name,questionId:q.id,answer,createdAt:now()});localStorage.setItem(`spark-live-${courseId}-${examId}-${user.uid}-${q.id}`,'1');render(s);});};unsubs.push(D.watch(ep()+'/live/state',render,error));return;}
page('Quiz ao vivo · '+e.title,`${select('live-question','Pergunta',e.questions.filter(q=>q.type!=='blanks').map(q=>[q.id,q.prompt]),state?.questionId)}${select('chart','Gráfico',[['bars','Barras'],['pie','Pizza'],['dots','Bolinhas'],['wordcloud','Nuvem de palavras']],'bars')}${select('values','Valores',[['count','Numérico'],['percent','Porcentagem']],'count')}<div class="actions">${button('live-open','Abrir pergunta')}${button('live-close','Encerrar pergunta','outline')}${button('live-end','Encerrar quiz','outline')}</div><p id="live-state"></p><div id="live-chart" class="card"></div>`);let responses=[];const render=()=>{const q=e.questions.find(q=>q.id===val('live-question')),rows=responses.filter(r=>r.questionId===q.id);$('live-chart').innerHTML=chart(q,rows,val('chart'),val('values'));};on('live-open',async()=>{const current=await D.read(ep()),time=releaseMillis(await D.serverNow());if((releaseMillis(current.startAt)||0)>time)throw Error('A liberação está agendada. Use Liberar agora para antecipar.');if((releaseMillis(current.endAt)||Infinity)<=time)throw Error('O prazo terminou. Ajuste o encerramento ou use Liberar agora.');await D.patch(ep(),{open:true,published:true,releaseMode:current.releaseMode==='scheduled'?'scheduled':'instant'});await D.put(ep()+'/live/state',{open:true,questionId:val('live-question')});$('live-state').textContent='Recebendo respostas. Cada estudante pode responder uma vez por pergunta.';});on('live-end',async()=>{await closeExam(e);await exams();});on('live-close',async()=>{await D.put(ep()+'/live/state',{open:false,questionId:val('live-question')});$('live-state').textContent='Respostas encerradas.';});for(const k of ['live-question','chart','values'])$(k).onchange=render;unsubs.push(D.watchList(ep()+'/liveAnswers',[],r=>{responses=r;render();},error));}
function chart(q,rows,type,values){const counts=new Map();if(q.options)q.options.forEach((v,i)=>counts.set(String(i),0));for(const r of rows){if(q.type==='multiple'&&Array.isArray(r.answer))for(const n of new Set(r.answer))if(counts.has(String(n)))counts.set(String(n),counts.get(String(n))+1);else{}else if(q.type==='choice'){if(counts.has(String(r.answer)))counts.set(String(r.answer),counts.get(String(r.answer))+1);}else if(typeof r.answer==='string'){const words=type==='wordcloud'?[...new Set(r.answer.toLocaleLowerCase('pt-BR').match(/[\p{L}\p{N}]+/gu)||[])]:[r.answer];for(const w of words)counts.set(w,(counts.get(w)||0)+1);}}const total=[...counts.values()].reduce((a,b)=>a+b,0),max=Math.max(1,...counts.values()),colors=['#176f60','#c76740','#4479af','#9064b1','#b29430','#3b8892'];const entries=[...counts].slice(0,100);const label=n=>values==='percent'?`${(n/Math.max(1,type==='pie'?total:rows.length)*100).toFixed(1)}%`:n;let visual='';if(type==='wordcloud')visual=entries.map(([k,n],i)=>`<span style="display:inline-block;margin:10px;color:${colors[i%6]};font-size:${16+32*n/max}px">${esc(q.options?q.options[Number(k)]:k)} (${label(n)})</span>`).join('');else if(type==='pie'){let angle=0;const stops=entries.filter(([,n])=>n>0).map(([,n],i)=>{const start=angle;angle+=n/Math.max(1,total)*360;return `${colors[i%6]} ${start}deg ${angle}deg`;});visual=`<div role="img" aria-label="Gráfico de pizza; dados na tabela abaixo" style="width:220px;height:220px;border-radius:50%;background:${stops.length?'conic-gradient('+stops.join(',')+')':'#ddd'}"></div>`;}else visual=entries.map(([k,n])=>`<p>${esc(q.options?q.options[Number(k)]:k)}: <strong>${label(n)}</strong></p>${type==='dots'?`<div aria-label="${n} respostas" style="color:#176f60;font-size:22px">${'● '.repeat(Math.min(n,60))}${n>60?' +'+(n-60):''}</div>`:`<div style="height:20px;background:#176f60;width:${n/max*100}%"></div>`}`).join('');return `<h2>${rows.length} respostas</h2><p>${q.type==='multiple'?'Múltiplas escolhas: barras/bolinhas usam respondentes; pizza usa marcações.':''}</p>${visual}${table(['Resposta','Contagem','Exibição'],entries.map(([k,n])=>[esc(q.options?q.options[Number(k)]:k),n,label(n)]))}`;}
async function tracking(){const students=await D.list(cp()+((owner()||!myTeachingSubjects.length)?'/students':'/roster')),records=await D.list(cp()+'/records',selectedSubject?[['subject','==',selectedSubject]]:[]);page(selectedSubject?'Acompanhamento · '+selectedSubject:'Acompanhamento geral',`<p>Vermelho: dois conceitos D ou uma nota inferior a 70% da escala. Resultados anteriores continuam visíveis nos períodos seguintes.</p>${table(['Aluno','Situação','Ação'],students.map(s=>{const results=latestResults(records.filter(r=>r.studentUid===s.uid&&r.kind==='result'));return [esc(s.name),risk(results)?'<strong style="color:#b42318">Acompanhamento prioritário</strong>':'Regular',button('student-'+s.uid,'Abrir histórico')];}))}`);for(const s of students)on('student-'+s.uid,()=>dossier(s));}
function latestResults(rows){const map=new Map();for(const r of rows.sort((a,b)=>(a.createdAt?.seconds||0)-(b.createdAt?.seconds||0)))map.set(r.subject+'|'+r.period,r);return [...map.values()];}
async function dossier(s){const records=await D.list(cp()+'/records',[['studentUid','==',s.uid],...(selectedSubject?[['subject','==',selectedSubject]]:[])]);page('Histórico · '+s.name,`${table(['Data','Tipo / disciplina / período','Autor','Resultado / observação','Documento'],records.sort((a,b)=>(b.createdAt?.seconds||0)-(a.createdAt?.seconds||0)).map(r=>[date(r.createdAt),esc([r.kind,r.subject,r.period].filter(Boolean).join(' / ')),esc(r.authorName),esc(r.kind==='result'?(r.grading==='concept'?r.concept:r.grade+' / '+r.scale)+' · '+r.text:r.text),r.kind==='written'?button('print-'+r.id,'Imprimir'):link(r.documentLink)]))}<h2>Novo lançamento</h2>${select('record-kind','Tipo',[['observation','Observação'],['result','Nota/conceito para conselho'],['verbal','Advertência verbal'],['written','Advertência escrita']],'observation')}${select('record-subject','Disciplina',(selectedSubject?[selectedSubject]:subjectsOf(course)).map(s=>[s,s]),selectedSubject||subjectsOf(course)[0])}${select('record-period','Período',course.periods.map(s=>[s,s]),course.periods[0])}<div id="record-evaluation-fields">${select('record-grading','Avaliação',[['concept','Conceito'],['grade','Nota']],'concept')}<div id="record-concept-fields">${select('record-concept','Conceito',['A','B','C','D'].map(s=>[s,s]),'A')}</div><div id="record-numeric-fields">${field('record-grade','Nota',0,'number')}${field('record-scale','Nota máxima',100,'number')}</div></div>${area('record-text','Observação / motivo da advertência')}${field('record-document','Documento adicional: link HTTPS')}${button('record-save','Registrar')}`);const updateRecordFields=()=>{const result=val('record-kind')==='result',numeric=result&&val('record-grading')==='grade';for(const [group,show] of [['record-evaluation-fields',result],['record-concept-fields',result&&!numeric],['record-numeric-fields',numeric]]){$(group).hidden=!show;for(const control of $(group).querySelectorAll('input,select'))control.disabled=!show;}};$('record-kind').onchange=updateRecordFields;$('record-grading').onchange=updateRecordFields;updateRecordFields();for(const r of records)on('print-'+r.id,()=>printWarning(s,r));on('record-save',async()=>{const kind=val('record-kind'),grade=Number(val('record-grade')),scale=Number(val('record-scale'));if(kind==='result'&&val('record-grading')==='grade'&&(!Number.isFinite(grade)||!Number.isFinite(scale)||scale<=0||grade<0||grade>scale))throw Error('Nota/escala inválida.');safeLink(val('record-document'));assertSubject(course,val('record-subject'));const r={kind,studentUid:s.uid,studentName:s.name,subject:val('record-subject'),period:val('record-period'),...(kind==='result'?(val('record-grading')==='concept'?{grading:'concept',concept:val('record-concept')}:{grading:'grade',grade,scale}):{}),text:val('record-text'),documentLink:val('record-document'),authorUid:user.uid,authorName:profile.name,createdAt:now(),header:course.warningHeader||'',footer:course.warningFooter||'',letterhead:course.letterhead||''};if(!r.text&&kind!=='result')throw Error('Descreva a observação/ocorrência.');await D.put(cp()+'/records/'+id(),r);dossier(s);});}
function printWarning(s,r){const w=window.open('','_blank');if(!w)throw Error('Permita a abertura da janela de impressão.');w.opener=null;w.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Advertência</title><style>body{font:16px Arial;margin:22mm;line-height:1.6}footer{margin-top:50px}a{word-break:break-all}</style></head><body><header>${esc(r.header)}</header><h1>Advertência por escrito</h1><p>Curso: ${esc(course.title)} · Turma: ${esc(course.group)}</p><p>Estudante: ${esc(s.name)}</p><p>Data: ${esc(date(r.createdAt))}</p><p style="white-space:pre-wrap">${esc(r.text)}</p><p>Responsável pelo registro: ${esc(r.authorName)}</p><p>${link(r.letterhead,'Modelo/papel timbrado externo')}</p><p>____________________________<br>Ciência do estudante / responsável</p><footer>${esc(r.footer)}</footer></body></html>`);w.document.close();w.print();}
async function report(){const students=await D.list(cp()+((owner()||!myTeachingSubjects.length)?'/students':'/roster')),all=await D.list(cp()+'/records',selectedSubject?[['subject','==',selectedSubject]]:[]),rows=[],subjects=selectedSubject?[selectedSubject]:[...new Set([...subjectsOf(course),...all.filter(r=>r.kind==='result'&&r.subject).map(r=>r.subject)])];for(const s of students)for(const subject of subjects){const results=latestResults(all.filter(r=>r.studentUid===s.uid&&r.subject===subject&&r.kind==='result'));rows.push([esc(s.name),esc(subject),...course.periods.map(p=>{const r=results.find(r=>r.period===p);return r?esc(r.grading==='concept'?r.concept:r.grade+' / '+r.scale):'—';})]);}const html=`<h1>${esc(course.title)}${selectedSubject?' · '+esc(selectedSubject):''} · Conselho acumulativo</h1><p>Períodos apresentados lado a lado, sem somar conceitos. Autor e revisões ficam no histórico do aluno.</p>${table(['Estudante','Disciplina',...course.periods.map(esc)],rows)}`;page('Relatório de conselho',html+button('report-print','Imprimir / salvar PDF')+button('report-download','Baixar relatório HTML','outline'));on('report-print',()=>window.print());on('report-download',()=>download('conselho-'+courseId+'.html','<!doctype html><meta charset="utf-8">'+html,'text/html'));return html;}
async function bankPanel(){const items=await D.list('sparkBank',[['ownerUid','==',user.uid]]);page('Banco de questões',`<p>Cadastre uma questão pelos campos abaixo. No cadastro da avaliação, você pode usar questões do seu banco.</p><div id="bank-question-editor"></div>${button('bank-save','Salvar questão')}<h2>Questões cadastradas</h2>${items.map(q=>`<details><summary>${esc(q.question.prompt)}</summary><p>${esc(q.question.type)} · Peso ${esc(q.question.points)}</p></details>`).join('')}`);const editor=mountQuestionEditor($('bank-question-editor'),[],{onError:error});editor.append();on('bank-save',async()=>{const questions=editor.read();if(questions.length!==1)throw Error('Preencha uma questão.');splitExam({...SAMPLE,questions});await D.put('sparkBank/'+id(),{ownerUid:user.uid,question:questions[0]});await bankPanel();});}

const childCollections=['instructors','roster','team','requests','students','lessons','progress','records','exams','closures'];
async function collectCourse(cid){const prefix='sparkCourses/'+cid,c=await D.read(prefix),out=[{path:prefix,data:D.encode(stripId(c))}];for(const col of childCollections){const rows=await D.list(prefix+'/'+col);for(const row of rows){const path=prefix+'/'+col+'/'+row.id;out.push({path,data:D.encode(stripId(row))});if(col==='exams')for(const sub of ['private','attempts','grades','events','live','liveAnswers'])for(const child of await D.list(path+'/'+sub))out.push({path:path+'/'+sub+'/'+child.id,data:D.encode(stripId(child))});}}return out;}
function stripId({id,...data}){return data;}
async function backupPanel(){page('Backup e restauração',`<p>Backup JSON desta edição Spark: perfis, planos, cursos, matrículas, conteúdos, avaliações, gabaritos, respostas, acompanhamento e demonstração. Não inclui contas do Authentication, documentos externos ou o cadastro de administradores.</p>${button('backup-export','Baixar backup completo')}<h2>Restaurar</h2><p>Restauração administrativa, em lotes. Sobrescreve caminhos presentes no JSON, preserva os demais e pode ficar parcial se houver falha. Guarde um backup atual antes de prosseguir.</p><input id="backup-file" type="file" accept="application/json">${field('restore-confirm','Digite RESTAURAR')}${button('backup-restore','Restaurar backup','danger')}<p id="backup-status"></p>`);on('backup-export',async()=>{const docs=[];for(const root of ['sparkProfiles','sparkInstitutions','sparkPlans','sparkPlanPayments','sparkInvites','sparkLeads','sparkBank'])for(const row of await D.list(root))docs.push({path:root+'/'+row.id,data:D.encode(stripId(row))});for(const c of await D.list('sparkCourses'))docs.push(...await collectCourse(c.id));download('conexoes-backup-'+new Date().toISOString().slice(0,10)+'.json',{format:'conexoes-spark-1',createdAt:new Date().toISOString(),docs});$('backup-status').textContent='Download solicitado. Confira se o arquivo foi salvo no computador.';});on('backup-restore',async()=>{if(val('restore-confirm')!=='RESTAURAR')throw Error('Confirme digitando RESTAURAR.');const f=$('backup-file').files[0];if(!f||f.size>20000000)throw Error('Selecione um JSON de até 20 MB.');const b=validateBackup(JSON.parse(await f.text()));if(!confirm(`Restaurar ${b.docs.length} documentos?`))return;await D.batch(b.docs.map(x=>({path:x.path,data:D.decode(x.data)})));$('backup-status').textContent='Restauração concluída.';});}
async function closure(){if(course.closed){return closedCourse();}
page('Fechamento do curso / ano',`<p>O relatório apresenta todos os períodos do curso e suas disciplinas. Feche cada curso do ano desejado separadamente.</p><p>Antes de encerrar, visualize os relatórios e confira o download do backup JSON.</p>${button('close-report','1. Visualizar e baixar relatório')}${button('close-backup','2. Baixar backup do curso')}<div id="close-output"></div><label><input id="close-read" type="checkbox"> Visualizei o relatório de fechamento.</label><label><input id="close-downloaded" type="checkbox"> Confirmei que o backup JSON foi salvo e pode ser recuperado.</label>${button('close-final','3. Encerrar e bloquear lançamentos','danger')}`);let viewed=false,downloaded=false,downloadHash='';on('close-report',async()=>{const students=await D.list(cp()+((owner()||!myTeachingSubjects.length)?'/students':'/roster')),records=await D.list(cp()+'/records');const html=`<h1>Fechamento · ${esc(course.title)}</h1><p>${esc(course.start)} a ${esc(course.end)}</p>${table(['Aluno','Disciplina','Período','Resultado','Autor','Observação'],records.map(r=>[esc(students.find(s=>s.uid===r.studentUid)?.name||r.studentName),esc(r.subject),esc(r.period),r.kind==='result'?esc(r.grading==='concept'?r.concept:r.grade+' / '+r.scale):esc(r.kind),esc(r.authorName),esc(r.text)]))}`;$('close-output').innerHTML=html;download('fechamento-'+courseId+'.html','<!doctype html><meta charset="utf-8">'+html,'text/html');viewed=true;});on('close-backup',async()=>{const docs=await collectCourse(courseId);download('curso-'+courseId+'.json',{format:'conexoes-spark-1',createdAt:new Date().toISOString(),docs});downloadHash=await fingerprint(docs);downloaded=true;});on('close-final',async()=>{if(!viewed||!downloaded||!$('close-read').checked||!$('close-downloaded').checked)throw Error('Conclua o relatório, o download e as confirmações.');if(await fingerprint(await collectCourse(courseId))!==downloadHash)throw Error('Dados mudaram após o backup. Gere novamente o relatório e o backup antes de encerrar.');await D.put(cp()+'/closures/'+id(),{authorUid:user.uid,authorName:profile.name,createdAt:now(),reportConfirmed:true,backupConfirmed:true,snapshotHash:downloadHash});await D.patch(cp(),{closed:true});openCourse(courseId);});}
async function renewPlan(){const plans=await D.list('sparkPlans');page('Meu plano e renovação',`<p>Plano atual: ${esc(profile.planId||'free')} · Validade: ${esc(date(profile.planExpiresAt))}</p><p>Realize o pagamento fora da aplicação e informe um link de comprovante que a administração consiga abrir.</p>${select('renew-plan','Plano',plans.length?plans.map(p=>[p.id,p.title]):[['free','Free']],profile.planId||'free')}${select('renew-cycle','Ciclo',[['monthly','Mensal'],['quarterly','Trimestral'],['semiannual','Semestral'],['yearly','Anual']],'monthly')}${field('renew-proof','Link HTTPS do comprovante')}${button('renew-send','Solicitar validação')}`);on('renew-send',async()=>{if(!val('renew-proof'))throw Error('Informe o comprovante.');safeLink(val('renew-proof'));await D.put('sparkPlanPayments/'+user.uid,{uid:user.uid,planId:val('renew-plan'),cycle:val('renew-cycle'),receiptLink:val('renew-proof'),createdAt:now()});alert('Solicitação enviada. A administração validará o comprovante e a data de vencimento.');home();});}
async function fingerprint(docs){const ordered=v=>Array.isArray(v)?v.map(ordered):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,ordered(v[k])])):v;const text=JSON.stringify(ordered([...docs].sort((a,b)=>a.path.localeCompare(b.path))));return [...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)))].map(n=>n.toString(16).padStart(2,'0')).join('');}
async function closedCourse(){page('Curso encerrado',`<p>Curso bloqueado para novos lançamentos. As contas e outros cursos serão preservados.</p>${button('closed-report','Visualizar e baixar relatório')}${isAdmin?button('closed-backup','Baixar backup atualizado'):''}<div id="closed-report-out"></div>${isAdmin?`<label><input id="purge-report" type="checkbox"> Visualizei os relatórios de fechamento.</label><label><input id="purge-backup" type="checkbox"> Confirmei que o backup JSON foi salvo e poderá ser recuperado.</label>${field('purge-text','Digite EXCLUIR '+courseId)}${button('purge','Excluir dados deste curso','danger')}`:''}`);let seen=false,downloaded=false,hash='';on('closed-report',async()=>{const records=await D.list(cp()+'/records');const html=`<h1>${esc(course.title)} · Fechamento</h1>${table(['Aluno','Disciplina','Período','Resultado / registro','Autor'],records.map(r=>[esc(r.studentName),esc(r.subject),esc(r.period),esc(r.kind==='result'?(r.grading==='concept'?r.concept:r.grade+' / '+r.scale):r.text),esc(r.authorName)]))}`;$('closed-report-out').innerHTML=html;download('fechamento-'+courseId+'.html','<!doctype html><meta charset="utf-8">'+html,'text/html');seen=true;});on('closed-backup',async()=>{const docs=await collectCourse(courseId);download('curso-encerrado-'+courseId+'.json',{format:'conexoes-spark-1',createdAt:new Date().toISOString(),docs});hash=await fingerprint(docs);downloaded=true;});on('purge',async()=>{if(!seen||!downloaded||!$('purge-report').checked||!$('purge-backup').checked||val('purge-text')!=='EXCLUIR '+courseId)throw Error('Visualize o relatório, baixe o backup e preencha todas as confirmações.');const docs=await collectCourse(courseId);if(await fingerprint(docs)!==hash)throw Error('Dados mudaram após o backup. Baixe novamente antes de excluir.');if(!confirm('A exclusão dos dados deste curso será definitiva no banco. Continuar?'))return;await D.batch(docs.reverse().map(d=>({path:d.path,delete:true})));await D.remove('sparkInvites/'+courseId);home();});}
function shareUrl(cid,eid='',quiz=false){const u=new URL(location.href);u.search='';u.hash='';u.searchParams.set('curso',cid);if(eid)u.searchParams.set('avaliacao',eid);if(quiz)u.searchParams.set('quiz','1');return u.href;}
async function routeLink(){const u=new URL(location.href),cid=u.searchParams.get('curso'),eid=u.searchParams.get('avaliacao');if(!cid||!/^[\w-]+$/.test(cid))return;try{await openCourse(cid);}catch(e){if(e.code==='permission-denied'){joinCourse();$('join-code').value=cid;return;}throw e;}if(eid&&/^[\w-]+$/.test(eid)){examId=eid;const e=await D.read(ep());if(!e)throw Error('Avaliação não encontrada.');selectedSubject=e.subject;if(e.mode==='live'||u.searchParams.get('quiz')==='1')await live(e);else await(subjectManager(e.subject)?reviewList(e):takeExam(e));}}

document.addEventListener('error',event=>{const image=event.target;if(image?.tagName==='IMG'&&image.classList.contains('material-image')){image.hidden=true;const fallback=image.closest('.material-visual')?.querySelector('.image-fallback');if(fallback)fallback.hidden=false;}},true);

async function reviewSubjectLinks(){
 const subjects=subjectsOf(course),links=[];
 for(const name of ['lessons','exams'])for(const entry of await D.list(cp()+'/'+name))if(!subjects.includes(entry.subject))links.push({collection:name,...entry});
 page('Revisar vínculos de disciplinas',`<p>Itens antigos sem uma disciplina válida podem ser vinculados aqui, preservando seus IDs e entregas. Conceitos históricos permanecem no conselho geral com a disciplina original.</p>${links.length?table(['Tipo','Item','Disciplina anterior','Vincular a','Ação'],links.map((entry,i)=>[entry.collection==='lessons'?'Conteúdo':'Avaliação',esc(entry.title),esc(entry.subject||'Sem disciplina'),select('link-subject-'+i,'Disciplina',subjects.map(subject=>[subject,subject]),subjects[0]),button('save-link-'+i,'Vincular')])):'<p>Todos os conteúdos e avaliações estão vinculados a disciplinas cadastradas.</p>'}`);
 links.forEach((entry,i)=>on('save-link-'+i,async()=>{const subject=assertSubject(course,val('link-subject-'+i));await D.patch(cp()+'/'+entry.collection+'/'+entry.id,{subject});await reviewSubjectLinks();}));
}
async function instructorsPanel(){
 const entries=await D.list(cp()+'/instructors'),subjects=subjectsOf(course);
 page('Coordenação e professores',`<div class="card"><h2>Coordenação do curso</h2><p>${esc(course.coordinatorName||course.ownerUid)}</p><p><code>${esc(course.ownerUid)}</code></p><p>O coordenador administra o curso, a equipe, as matrículas e o conselho geral. Um professor pode lecionar em uma ou mais disciplinas, sem acesso às demais.</p></div><h2>Professores cadastrados no curso</h2>${table(['Professor','UID','Disciplinas','Ação'],entries.map((e,i)=>[esc(e.name),esc(e.uid),esc(e.subjects.join(', ')),button('edit-instructor-'+i,'Editar','outline')+button('remove-instructor-'+i,'Revogar','danger')]))}<h2>Atribuir disciplinas</h2><p>Informe o UID de um professor já aprovado, da mesma instituição e campus. O professor encontra o UID no cadastro/conta. Se outra pessoa já for responsável por uma disciplina selecionada, a atribuição será transferida para o professor informado.</p>${field('instructor-uid','UID do professor')}${field('instructor-name','Nome do professor')}<div id="instructor-subjects">${subjects.map((subject,i)=>`<label><input type="checkbox" data-instructor-subject="${i}"> ${esc(subject)}</label>`).join('')}</div>${button('instructor-save','Salvar atribuição')}<hr><h2>Transferir a coordenação</h2><p>Somente o coordenador atual ou administrador pode transferir. Para continuar lecionando após a transferência, atribua antes suas disciplinas ao seu próprio UID.</p>${field('coordinator-uid','UID do novo coordenador')}${field('coordinator-name','Nome do novo coordenador')}${button('coordinator-transfer','Transferir coordenação','outline')}`);
 entries.forEach((entry,i)=>{on('edit-instructor-'+i,()=>{$('instructor-uid').value=entry.uid;$('instructor-name').value=entry.name;for(const input of document.querySelectorAll('[data-instructor-subject]'))input.checked=entry.subjects.includes(subjects[Number(input.dataset.instructorSubject)]);});on('remove-instructor-'+i,async()=>{if(!confirm('Revogar o acesso de '+entry.name+' às disciplinas deste curso?'))return;await D.remove(cp()+'/instructors/'+entry.uid);await removeInstructorViewer(entry.uid);await instructorsPanel();});});
 on('instructor-save',async()=>{const uid=val('instructor-uid'),name=val('instructor-name'),chosen=[...document.querySelectorAll('[data-instructor-subject]:checked')].map(input=>subjects[Number(input.dataset.instructorSubject)]);if(!/^[\w-]+$/.test(uid)||!name||!chosen.length)throw Error('Informe UID, nome e ao menos uma disciplina.');const operations=[],revoked=[];for(const entry of entries){if(entry.uid===uid)continue;const remaining=entry.subjects.filter(subject=>!chosen.includes(subject));if(remaining.length===entry.subjects.length)continue;if(remaining.length)operations.push({path:cp()+'/instructors/'+entry.uid,data:{uid:entry.uid,name:entry.name,subjects:remaining}});else{operations.push({path:cp()+'/instructors/'+entry.uid,delete:true});revoked.push(entry.uid);}}operations.push({path:cp()+'/instructors/'+uid,data:{uid,name,subjects:chosen}});for(const student of await D.list(cp()+'/students'))operations.push({path:cp()+'/roster/'+student.uid,data:{uid:student.uid,name:student.name||'',email:student.email||'',active:student.active===true}});await D.batch(operations);await D.patch(cp(),{viewerUids:D.arrayUnion(uid)});for(const previousUid of revoked)await removeInstructorViewer(previousUid);await instructorsPanel();});
 on('coordinator-transfer',async()=>{const uid=val('coordinator-uid'),name=val('coordinator-name');if(!/^[\w-]+$/.test(uid)||!name)throw Error('Informe UID e nome do novo coordenador.');if(!confirm('Transferir a coordenação? Você perderá os poderes de coordenador neste curso.'))return;await D.patch(cp(),{ownerUid:uid,coordinatorName:name,viewerUids:D.arrayUnion(uid)});await home();});
}
async function removeInstructorViewer(uid){if(uid===course.ownerUid)return;const team=await D.read(cp()+'/team/'+uid),student=await D.read(cp()+'/students/'+uid);if(!team&&!student)await D.patch(cp(),{viewerUids:D.arrayRemove(uid)});}
async function subjectsPanel(){
 course=await D.read(cp());const subjects=subjectsOf(course),single=course.subjectMode==='single'||(!course.subjectMode&&subjects.length<=1);
 page('Adicionar disciplinas',`<p>${esc(course.title)} · ${single?'Uma disciplina':'Várias disciplinas'}</p>${table(['Disciplina','Ação'],subjects.map((subject,i)=>[esc(subject),button('remove-subject-'+i,'Remover','outline')]))}${!course.closed?`${field('new-subject-name','Nome da disciplina')}${button('new-subject-save','Adicionar disciplina')}`:'<p>Curso encerrado. Não é possível alterar disciplinas.</p>'}<p>Disciplinas com conteúdos, avaliações, professores ou conceitos vinculados não podem ser removidas.</p>`,()=>openCourse(courseId));
 on('new-subject-save',async()=>{if(course.closed)throw Error('Curso encerrado.');const [name]=validateSubjects('single',[val('new-subject-name')]);if(subjects.some(s=>s.toLocaleLowerCase('pt-BR')===name.toLocaleLowerCase('pt-BR')))throw Error('Esta disciplina já está cadastrada.');if(single&&subjects.length)throw Error('Este curso permite uma disciplina. Altere para Várias disciplinas nas configurações para adicionar outra.');if(subjects.length>=100)throw Error('Limite de cem disciplinas.');await D.patch(cp(),{subjects:D.arrayUnion(name)});await subjectsPanel();});
 subjects.forEach((subject,i)=>on('remove-subject-'+i,async()=>{if(course.closed)throw Error('Curso encerrado.');for(const collection of ['lessons','exams','records','instructors']){const associated=await D.list(cp()+'/'+collection);if(associated.some(x=>x.subject===subject||(x.subjects||[]).includes(subject)))throw Error('Esta disciplina possui vínculos. Preserve-a para manter o histórico.');}if(!confirm('Remover a disciplina '+subject+'?'))return;await D.patch(cp(),{subjects:D.arrayRemove(subject)});await subjectsPanel();}));
}
async function organizeLessons(){
 if(!requireSubject())return;if(!subjectManager()||course.closed)throw Error('Você não pode organizar estes conteúdos.');
 const items=orderedLessons(await D.list(cp()+'/lessons',[['subject','==',selectedSubject]]));
 page('Organizar assuntos e ordem',`<p>Organize a sequência com Subir e Descer. Você também pode classificar os conteúdos por assunto/unidade e usar o filtro na lista. Clique em Salvar organização para publicar.</p><div id="lesson-order-list">${items.map((item,i)=>`<section class="card lesson-order-row" data-lesson-id="${esc(item.id)}"><h2>${esc(item.title)}</h2>${field('order-topic-'+i,'Assunto / unidade',item.topic)}<div class="actions">${button('lesson-up-'+i,'↑ Subir','outline')}${button('lesson-down-'+i,'↓ Descer','outline')}</div></section>`).join('')}</div>${button('save-lesson-order','Salvar organização')}`,lessons);
 items.forEach((item,i)=>{on('lesson-up-'+i,()=>{const row=$('lesson-up-'+i).closest('[data-lesson-id]');if(row.previousElementSibling)row.parentElement.insertBefore(row,row.previousElementSibling);});on('lesson-down-'+i,()=>{const row=$('lesson-down-'+i).closest('[data-lesson-id]');if(row.nextElementSibling)row.parentElement.insertBefore(row.nextElementSibling,row);});});
 on('save-lesson-order',async()=>{const operations=[...$('lesson-order-list').children].map((row,i)=>{const original=items.find(x=>x.id===row.dataset.lessonId);return {path:cp()+'/lessons/'+original.id,data:{...stripId(original),topic:row.querySelector('input').value.trim(),order:(i+1)*10,updatedAt:now()}};});await D.batch(operations);await lessons();});
}

async function initializeLessonRelease(items){const epoch=D.Timestamp.fromMillis(0);for(const lesson of items)if(!lesson.releaseAt){await D.patch(cp()+'/lessons/'+lesson.id,{releaseMode:'instant',releaseAt:epoch});lesson.releaseMode='instant';lesson.releaseAt=epoch;}return items;}

async function publishInstitution(person){const key=person.institutionKey||institutionKey(person.institution),path='sparkInstitutions/'+key,entry=await D.read(path);if(entry){if(!(entry.campuses||[]).includes(person.campus))await D.patch(path,{campuses:D.arrayUnion(person.campus)});}else await D.put(path,{name:person.institution,campuses:[person.campus]});}
async function campusPanel(){const key=profile.institutionKey||institutionKey(profile.institution),path='sparkInstitutions/'+key;let entry=await D.read(path);if(!entry){await D.put(path,{name:profile.institution,campuses:[profile.campus]});entry=await D.read(path);}page('Instituição e campi',`<p><strong>${esc(entry.name)}</strong></p>${table(['Campi cadastrados'],entry.campuses.map(name=>[esc(name)]))}${field('campus-new-name','Nome do novo campus')}${button('campus-add','Cadastrar campus')}<p>O campus ficará disponível para novos cadastros de professores, equipe e estudantes. Seu próprio cadastro e os cursos existentes não mudam de campus.</p>`);on('campus-add',async()=>{const name=campusName(val('campus-new-name'));if(entry.campuses.some(c=>c.toLocaleLowerCase('pt-BR')===name.toLocaleLowerCase('pt-BR')))throw Error('Este campus já está cadastrado.');await D.patch(path,{campuses:D.arrayUnion(name)});await campusPanel();});}

function availabilityFields(e){const mode=e.releaseMode||(e.open?((releaseMillis(e.startAt)||0)>Date.now()?'scheduled':'instant'):'manual'),end=releaseMillis(e.endAt);return `<div class="card"><h2>Liberação e encerramento</h2>${select('exam-release-mode','Quando liberar',[['manual','Manter fechada até liberação manual'],['instant','Liberar imediatamente'],['scheduled','Agendar data e horário']],mode)}<div id="exam-schedule-fields">${field('exam-release-at','Data e horário de liberação — Brasília',scheduledInput(e.startAt),'datetime-local')}</div>${field('exam-close-at','Encerrar respostas automaticamente em (opcional) — Brasília',end&&end<Date.parse('2100-01-01T00:00:00Z')?scheduledInput(e.endAt):'','datetime-local')}<p>Horário de Brasília (UTC−03:00). No quiz ao vivo, o professor também precisa abrir cada pergunta.</p></div>`;}
function wireAvailability(){const toggle=()=>{$('exam-schedule-fields').hidden=val('exam-release-mode')!=='scheduled';};$('exam-release-mode').onchange=toggle;toggle();}
function readAvailability(){const setting=availabilitySpec(val('exam-release-mode'),val('exam-release-at'),val('exam-close-at'));return {releaseMode:setting.releaseMode,open:setting.open,startAt:D.Timestamp.fromMillis(setting.startMillis),endAt:D.Timestamp.fromMillis(setting.endMillis)};}
async function closeExam(e){await D.patch(ep(),{open:false,releaseMode:'manual'});if(e.mode==='live'){const state=await D.read(ep()+'/live/state');if(state)await D.patch(ep()+'/live/state',{open:false});}}
async function releaseExamNow(e){const now=releaseMillis(await D.serverNow());await D.patch(ep(),{open:true,published:true,releaseMode:'instant',startAt:D.Timestamp.fromMillis(0),endAt:(releaseMillis(e.endAt)||0)>now?e.endAt:D.Timestamp.fromMillis(Date.parse('2100-01-01T00:00:00Z'))});}
async function examAvailability(e){page('Liberação da avaliação',`${availabilityFields(e)}${button('save-availability','Salvar liberação e encerramento')}${button('close-availability','Encerrar respostas agora','outline')}`,exams);wireAvailability();on('save-availability',async()=>{const data=readAvailability();await D.patch(ep(),{...data,published:true});if(!data.open&&e.mode==='live'){const state=await D.read(ep()+'/live/state');if(state)await D.patch(ep()+'/live/state',{open:false});}await exams();});on('close-availability',async()=>{await closeExam(e);await exams();});}
async function assertExamWindow(e,fail){const current=await D.read(ep()),now=releaseMillis(await D.serverNow()),ok=current?.open&&now>=(releaseMillis(current.startAt)||0)&&now<(releaseMillis(current.endAt)||Infinity);if(!ok&&fail)throw Error('Esta atividade não está recebendo respostas: aguarde a liberação ou consulte o professor.');return ok;}

function responseText(q,value){
 if(value===undefined||value===null)return 'Sem resposta registrada';
 const option=index=>q.options&&Number.isInteger(index)&&index>=0&&index<q.options.length?String.fromCharCode(65+index)+') '+q.options[index]:String(index);
 if(q.type==='choice')return option(value);
 if(q.type==='multiple')return Array.isArray(value)?(value.length?value.map(option).join('\n'):'Nenhuma alternativa marcada'):String(value);
 if(q.type==='blanks')return Array.isArray(value)?value.map((text,i)=>'Lacuna '+(i+1)+': '+text).join('\n'):String(value);
 return typeof value==='string'?value:typeof value==='object'?JSON.stringify(value):String(value);
}
function responseMoment(value){const millis=releaseMillis(value);return millis===null?date(value):new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',dateStyle:'short',timeStyle:'medium'}).format(new Date(millis));}
function resultLabel(exam,grade){return !grade?'A corrigir':exam.grading==='concept'?grade.concept:grade.grade+' / '+exam.scale;}
async function responseReport(original){
 examId=original.id;const e=await D.read(ep());if(!e)throw Error('Atividade não encontrada.');selectedSubject=e.subject;if(!subjectManager(e.subject))throw Error('Você não pode consultar estas respostas.');
 const students=await D.list(cp()+((owner()||!myTeachingSubjects.length)?'/students':'/roster'));
 const quiz=e.mode==='live',answers=await D.list(ep()+(quiz?'/liveAnswers':'/attempts')),grades=quiz?[]:await D.list(ep()+'/grades');
 const people=new Map(students.map(student=>[student.uid||student.id,{uid:student.uid||student.id,name:student.name||student.uid||student.id}]));
 for(const answer of answers)if(!people.has(answer.uid))people.set(answer.uid,{uid:answer.uid,name:answer.name||answer.uid});
 const participants=[...people.values()].sort((a,b)=>a.name.localeCompare(b.name,'pt-BR')||a.uid.localeCompare(b.uid));
 const questions=[...e.questions];if(quiz)for(const answer of answers)if(!questions.some(q=>q.id===answer.questionId))questions.push({id:answer.questionId,type:'open',prompt:'Questão do histórico ('+answer.questionId+')'});
 page(quiz?'Respostas individuais do quiz':'Respostas das avaliações individuais',`<p><strong>${esc(e.title)}</strong> · ${esc(e.subject)} · ${esc(course.group)}</p><p>${esc(availabilityStatus(e))}</p><p>Consulta dos registros salvos. Esta tela não abre perguntas nem libera respostas.</p>${button('responses-refresh','Atualizar consulta','outline')}${select('responses-student','Aluno',[['','Todos os alunos'],...participants.map(p=>[p.uid,p.name])],'')}${quiz?select('responses-question','Pergunta',[['','Todas as perguntas'],...questions.map((q,i)=>[q.id,(i+1)+'. '+q.prompt.slice(0,100)])],''):''}<div id="responses-output"></div>`,exams);
 const render=()=>{const uid=val('responses-student'),questionId=quiz?val('responses-question'):'',visible=participants.filter(p=>!uid||p.uid===uid);
 if(!visible.length){$('responses-output').innerHTML='<p>Nenhum aluno ou resposta foi encontrado para esta atividade.</p>';return;}
 if(quiz){const selected=questions.filter(q=>!questionId||q.id===questionId);$('responses-output').innerHTML=table(['Aluno','Respostas registradas','Ação'],visible.map(p=>{const received=answers.filter(a=>a.uid===p.uid&&selected.some(q=>q.id===a.questionId)).length;return [esc(p.name),received+' de '+selected.length,button('quiz-details-'+p.uid,'Ver respostas')];}));for(const person of visible)on('quiz-details-'+person.uid,()=>{page('Respostas do quiz · '+person.name,`<p><strong>${esc(e.title)}</strong> · ${esc(e.subject)}</p><p>Aluno: ${esc(person.name)}</p>${table(['Pergunta','Resposta do aluno','Enviada em — Brasília'],selected.map((q,i)=>{const answer=answers.find(a=>a.uid===person.uid&&a.questionId===q.id);return [esc(q.prompt),'<div class="review-answer">'+esc(responseText(q,answer?.answer))+'</div>',answer?esc(responseMoment(answer.createdAt)):'—'];}))}`,()=>responseReport(e));});
 }else{$('responses-output').innerHTML=table(['Aluno','Situação','Entrega — Brasília','Resultado','Ações'],visible.map(p=>{const answer=answers.find(a=>a.uid===p.uid),grade=grades.find(g=>g.id===p.uid);return [esc(p.name),answer?'Entregue':'Sem entrega',answer?esc(responseMoment(answer.submittedAt)):'—',answer?esc(resultLabel(e,grade)):'—',answer?button('attempt-details-'+p.uid,'Ver respostas')+(!course.closed?button('attempt-review-'+p.uid,'Corrigir','outline'):''):'—'];}));for(const person of visible){const answer=answers.find(a=>a.uid===person.uid);if(!answer)continue;const grade=grades.find(g=>g.id===person.uid);on('attempt-details-'+person.uid,()=>individualResponse(e,answer,grade));on('attempt-review-'+person.uid,()=>review(e,answer));}}
 };
 $('responses-student').onchange=render;if(quiz)$('responses-question').onchange=render;on('responses-refresh',()=>responseReport(e));render();
}
function individualResponse(e,answer,grade){page('Resposta individual · '+answer.name,`<p><strong>${esc(e.title)}</strong> · ${esc(e.subject)}</p><p>Aluno: ${esc(answer.name)} · Entrega: ${esc(responseMoment(answer.submittedAt))} (Brasília)</p><p>Resultado: <strong>${esc(resultLabel(e,grade))}</strong></p>${e.questions.map((q,i)=>{const feedback=grade?.feedback?.[q.id];return `<section class="card"><h2>${i+1}. ${esc(q.prompt)}</h2>${q.code?`<pre style="background:#101418;color:#e8edf2;padding:18px;white-space:pre-wrap"><code>${esc(q.code)}</code></pre>`:''}<h3>Resposta do aluno</h3><div class="review-answer">${esc(responseText(q,answer.answers?.[q.id]))}</div>${feedback?`<p>Pontos: ${esc(feedback.points)} de ${esc(q.points)}</p><p>Feedback: ${esc(feedback.feedback||'Sem comentário adicional.')}</p>`:'<p>Aguardando correção.</p>'}</section>`;}).join('')}${grade?.reason?'<p>Justificativa do desconto: '+esc(grade.reason)+'</p>':''}${!course.closed?button('response-correct','Abrir correção','outline'):''}`,()=>responseReport(e));on('response-correct',()=>review(e,answer));}
